# ----------------------------------------------------------------------------------------------------------------------------------------------
# Rules in plain English (sheet F)

RULES: list[dict[str, str]] = [
    {"section": "Aspects", "term": "The seven Aspects", "meaning": "Reason, Empathy, Authority, Guile, Resolve, Curiosity and Wonder. Each is a score from 0 to 5. A new apprentice starts with Reason 2, Empathy 2, Authority 1, Guile 1, Resolve 2, Curiosity 3, Wonder 2. Every wizard has their own scores.", "where": "config.json campaign.start_aspects; sim/dmb/narrative/aspects.py"},
    {"section": "Aspects", "term": "How scores change", "meaning": "Only through a dialogue effect, by exactly +1 or −1, once per effect. The game currently contains only +1 effects: Reason +1 (finding the granite) and Resolve +1 (beating the stranger). Scores never go down.", "where": "graph._aspect, campaign.on_duel_resolved"},
    {"section": "Skill checks", "term": "The check", "meaning": "No dice. Total = Aspect score + evidence bonus + regard bonus. You pass if the total is at least the threshold. The same situation always gives the same result.", "where": "AspectService.check"},
    {"section": "Skill checks", "term": "Difficulty", "meaning": "easy = 2, demanding = 4, exceptional = 6. (No check in the game uses exceptional.)", "where": "THRESHOLDS"},
    {"section": "Skill checks", "term": "Evidence bonus", "meaning": "Each check lists pieces of evidence (a lesson done, a fact learned, something you witnessed). Each that applies adds its bonus (usually +1); the total evidence is capped at +2.", "where": "checks._evidence"},
    {"section": "Skill checks", "term": "Regard bonus", "meaning": "How the person you are speaking to feels about you (−100 to +100): +1 if 25 or more, −1 if −25 or less, otherwise 0. The mentor starts at 40 (+1), the mother at 60, everyone else at 0.", "where": "relationship_band"},
    {"section": "Skill checks", "term": "Failing and trying again", "meaning": "A failed check is remembered. The button is greyed out (‘disabled’) until something that counts changes: your score, the evidence, or the regard band. A passed check stays passed and is never rolled again. If a failed attempt is sent anyway, the engine says ‘You have nothing new to add.’", "where": "checks.retry_blocked, graph.run_block"},
    {"section": "Skill checks", "term": "Multiplayer quirk", "meaning": "The memory of failed attempts is shared by the world, not kept per wizard. If one wizard fails a check, a second wizard with exactly the same numbers is told ‘You have nothing new to add’ on their first try (DEF-07).", "where": "AspectService failed_fingerprints; probe P44"},
    {"section": "Regard", "term": "Regard (disposition)", "meaning": "A number from −100 to +100 for each person's feeling about each wizard. Dialogue effects add or subtract (for example +5, −3, +10). Its only visible effects are: the ±25 bonus in skill checks, and three lines that test it directly: a ‘wary’ remark when a wary villager's regard is 5 or less, the promise to ‘ask around’ when regard is 10 or more, and the thank-you topic about the Forest Dispute (regard 10 or more).", "where": "graph._relationship; occupations/aftermath ‘relationship’ conditions"},
    {"section": "Worldviews", "term": "The seven worldviews", "meaning": "M Monarchist · A Anarchist · R Religious · G Guildist · S Arcane Supremacist · D Druidic · C Illuminated / Mad. Choosing a belief reply adds that view's row of the table to your own seven scores (+3 to the chosen view, small ± to the others). Your strongest view is your ‘primary worldview’. Nothing in the current dialogue tests it (DEF-10).", "where": "worldviews.json; wizard.apply_worldview_choice"},
    {"section": "Worldviews", "term": "How a person reacts to your belief", "meaning": "Take the person's main worldview and look up the table value for the reply's view; add 1 if their second worldview is the reply's view. 2 or more → they agree (their regard for you +4). −1 or less → they disagree (−3). Otherwise neutral (no change). Each person answers one belief reply per topic. See sheet J for the full grid.", "where": "personas.affinity / reaction; graph.respond"},
    {"section": "Worldviews", "term": "Your worldview shift is once per answer", "meaning": "The shift is recorded once per distinct answer. Giving the same belief reply on the same topic to a second villager changes the villager's regard but not your worldview scores again.", "where": "graph.respond receipts"},
    {"section": "Personality", "term": "Persona", "meaning": "Main and second worldview, two traits, an attitude to the mentor (fond / respectful / wary) and an attitude to magic (devoted / reverent / cautious / wary / practical). Dialogue lines can require any of these.", "where": "personas.py"},
    {"section": "Knowledge", "term": "Knowledge of the attack", "meaning": "none (before the attack) · witnessed (the person was within 12 tiles of the mentor when the stranger came, or is the stranger or mentor) · rumour (everyone else). Witnesses know the stranger's name; others say ‘the stranger’.", "where": "campaign.knowledge"},
    {"section": "Knowledge", "term": "Learned facts", "meaning": "Things you have learned from a conversation (for example ‘the mentor admitted the light is an older craft’). They are per wizard. A line or an evidence bonus can require them.", "where": "wizard.learn_fact"},
    {"section": "Flags", "term": "Dialogue flags", "meaning": "Each conversation file remembers small facts per wizard: who you have heard, which ending you chose, which closing words were spoken. A line or choice can require a flag or forbid it. Flags are the way a conversation ‘remembers’ within a quest.", "where": "graph.flags; sheet H"},
    {"section": "Flags", "term": "Effects happen once", "meaning": "Nearly every effect (regard, Aspect, fact, journal note, ware) carries a receipt and is applied once per wizard even if the line is heard again. Ledger counts and duel starts are the exceptions and repeat.", "where": "graph.apply / REPEATABLE"},
    {"section": "Entries", "term": "First matching entry", "meaning": "A speaker's node has an ordered list of entries. The game speaks the first entry whose conditions hold and ignores the rest. An entry with no condition therefore hides every entry after it.", "where": "graph.view"},
    {"section": "Entries", "term": "Alternate wordings", "meaning": "Some entries (the mother, the keeper) carry extra wordings and rotate through them each time the entry is heard again.", "where": "graph.view (lines_alt)"},
    {"section": "Everyday talk", "term": "How topics are chosen", "meaning": "Every ordinary person has questions for their trade plus shared ones. Questions whose conditions fail are hidden. Up to three ‘priority’ questions are listed first, then three more from the rest, rotating with the number of times you have spoken to that person. A question you have asked in this conversation is not repeated.", "where": "occupations.view"},
    {"section": "Everyday talk", "term": "First and later meetings", "meaning": "The introduction is spoken the first time; later conversations use a greeting. Both are chosen by a seeded draw, so the same person says the same thing. The count is shared by all wizards in the world (DEF-08).", "where": "occupations.view"},
    {"section": "Everyday talk", "term": "Live facts", "meaning": "Lines may use facts read from the simulation at that moment: trees near the person, logs in the stores, soldiers, whether a barracks exists, whether an enemy is within 25 tiles, what they are carrying. A line whose fact is false is never offered.", "where": "occupations.facts_for"},
    {"section": "Availability", "term": "Hidden", "meaning": "A line or choice is not shown because its conditions do not hold (a flag is missing, a lesson is not done, the stage is wrong, a fact is false). It may appear later.", "where": "graph.holds"},
    {"section": "Availability", "term": "Disabled", "meaning": "A skill-check choice that failed and cannot be retried until something changes. It stays visible but greyed out.", "where": "available:false"},
    {"section": "Availability", "term": "Consumed / completed", "meaning": "A single-use choice already taken (‘once’), a choice whose forbidding flag is set, a conversation answered once (belief replies), or an ending already chosen. It does not come back.", "where": "graph.choose (done:<id>)"},
    {"section": "Availability", "term": "Inaccessible", "meaning": "The person cannot be spoken to: dead, gone, too far (more than 3 tiles), a duel or a scene is open, the game is over, a rat, a soldier who is fighting (‘Not now. Can’t you see I am busy?’), the stranger before his scene (‘…as if you were furniture’), a worker inside a building (ask them out first). Mira is not talkable.", "where": "conversation.talk; probe P39, P46"},
    {"section": "Availability", "term": "Broken", "meaning": "Dialogue that can never be reached because of a logic error: see sheet N.", "where": "—"},
    {"section": "Conversation", "term": "Range and ending", "meaning": "You must be within 3 tiles. Walking more than 6 tiles away, leaving, pressing Escape, a duel starting, loading a save, the person dying, or two idle game-minutes all end it. The person is held in place meanwhile; the rest of the world keeps running.", "where": "conversation.py"},
    {"section": "Campaign", "term": "Stages and timing", "meaning": "training → explore → arrival → confrontation → duel → victory → aftermath → complete (or game over). Training ends when the four lessons are done, or a wizard duel or death has happened, or after 5 minutes of game time. The stranger comes after 3 minutes with 3 contacts, or after 7 minutes whatever happened, and only when nothing else owns the player. The introduction completes after 2 villager conversations or 150 seconds.", "where": "config.json campaign; campaign.py"},
    {"section": "Campaign", "term": "Stories unlock", "meaning": "The village quests are available once all four lessons are done, or 20 game-minutes have passed.", "where": "graph.unlocked"},
    {"section": "Multiplayer", "term": "Private to each wizard", "meaning": "Spells, lessons, facts, journal, worldview scores, Aspect scores, dialogue flags and ending choices, the scene being read, who they have spoken to, regard in each person's eyes.", "where": "party.py"},
    {"section": "Multiplayer", "term": "Shared by the world", "meaning": "The settlement and its people, the quest cast, the campaign stage, the clock, the stranger and the mentor's body, the number of times a villager has been spoken to, which villagers have already given their first reaction to the attack, and the memory of failed skill checks.", "where": "party.py; probes P35, P44"},
    {"section": "Ledger", "term": "The behaviour ledger", "meaning": "Counts what wizards have done: wizard duels, wins, losses, kills, deaths, resurrections, draws, protests, provocations, refused steps, rat kills, burned warehouses, Trial deeds. Lines read them as facts, either for the world or ‘my_’ for the wizard speaking.", "where": "ledger.py"},
]

